{
  "name": "Arbin电池循环测试仪",
  "name_en": "Arbin Battery Cycler",
  "manufacturer": "Arbin Instruments",
  "description": "多通道电池循环测试仪，用于对电池或电芯进行充放电循环测试、通道状态监测和性能评估，常用于电池研发与测试实验室。",
  "description_en": "A multi-channel battery cycler used for charge-discharge cycling tests, channel status monitoring, and performance evaluation of batteries or cells in battery R&D and testing laboratories.",
  "tag_hints": [
    "battery cycling",
    "battery testing",
    "charge-discharge testing",
    "multi-channel tester",
    "cell characterization",
    "electrochemistry"
  ],
  "actions": [
    {
      "action_name": "get_num_channels",
      "description": "获取循环测试仪的通道数量",
      "description_en": "Get the number of channels on the cycler."
    },
    {
      "action_name": "get_login_feedback",
      "description": "获取登录反馈信息",
      "description_en": "Get the login feedback message."
    },
    {
      "action_name": "auto-read_channel_status",
      "description": "读取指定通道的状态",
      "description_en": "Read the status of the specified channel."
    }
  ]
}

